function execute_request(array $u,array $r,array $p,string $evidence):void {
 if(cash_execute($u,$r,$p,$evidence))return;
 if(governance_execute($u,$r,$p,$evidence))return;
 if(configuration_plan($u,$r,$p)){promote_configuration();return;}
 $kind=$r['kind'];$target=(int)($p['user_id']??$r['user_id']);
 if($kind==='recovery'){$i=row('SELECT * FROM rs_intakes WHERE id=? FOR UPDATE',[required($p,'intake_id',32)])??fail(404,'Intake not found.');if($i['status']!=='verified')fail(409,'Recovery verification state changed.');sql('INSERT INTO rs_recovery_grants(intake_id,user_id,expires_at) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 24 HOUR))',[$i['id'],$target]);sql('UPDATE rs_intakes SET status="approved",public_reply="Your verified recovery was approved. Use your private access key to set a new password within 24 hours.",version=version+1,updated_at=UTC_TIMESTAMP() WHERE id=?',[$i['id']]);return;}
 if(in_array($kind,['refund','fare_adjustment'])){
  $trip=trip_row($r['trip_id'],true);if((int)($p['trip_version']??0)!==(int)$trip['version'])fail(409,'The trip financial state changed after review. Submit a new proposal.');$amount=(int)($p['amount_minor']??-1);if($amount<1||$amount>(int)$trip['fare_minor'])fail(422,'Amount must be within the original fare.');
  if($kind==='refund'&&!in_array($trip['payment_status'],['collected','partially_collected','partially_refunded','disputed']))fail(409,'No collection evidence exists for this refund.');
  if($kind==='fare_adjustment'){
   if(!in_array($trip['payment_status'],['uncollected','partially_collected']))fail(409,'Resolve the current collection state first, or use a refund for collected money.');$remaining=(int)sql('SELECT COALESCE(SUM(e.amount_minor),0) FROM rs_entries e JOIN rs_journals j ON j.id=e.journal_id WHERE j.trip_id=? AND e.account_key="customer_receivable"',[$trip['id']])->fetchColumn();if($amount>$remaining)fail(422,'The adjustment exceeds the verified remaining obligation.');
   journal($u,'fare_adjustment','fare_adjustment:'.$r['id'],$trip['id'],[['account'=>'fare_adjustment','amount'=>$amount],['account'=>'customer_receivable','user'=>(int)$trip['customer_id'],'amount'=>-$amount]],$evidence);sql('UPDATE rs_trips SET fare_minor=fare_minor-?,payment_status=IF(?=0,"settled_adjusted",payment_status),version=version+1 WHERE id=?',[$amount,$remaining-$amount,$trip['id']]);notify((int)$trip['customer_id'],'payment','Fare adjustment recorded','Your independently reviewed remaining obligation and receipt were updated. Driver earnings are unchanged.',$trip['id']);return;
  }
  $collected=(int)sql('SELECT COALESCE(SUM(-e.amount_minor),0) FROM rs_entries e JOIN rs_journals j ON j.id=e.journal_id WHERE j.trip_id=? AND e.account_key="customer_receivable" AND j.kind IN ("cash_collection","manual_collection","cash_report_reversal")',[$trip['id']])->fetchColumn();if($kind==='refund'&&$trip['payment_status']==='disputed'&&!row('SELECT id FROM rs_journals WHERE reference_key=?',['cash-resolution:'.$trip['id']]))fail(409,'Resolve the disputed collection before refunding it.');
  $refunded=(int)sql('SELECT COALESCE(SUM(e.amount_minor),0) FROM rs_entries e JOIN rs_journals j ON j.id=e.journal_id WHERE j.trip_id=? AND j.kind="refund" AND e.account_key="refund_expense"',[$trip['id']])->fetchColumn();if($kind==='refund'&&$amount+$refunded>$collected)fail(422,'This refund exceeds the remaining refundable collection.');
  journal($u,$kind,$kind.':'.$r['id'],$trip['id'],[['account'=>$kind==='refund'?'refund_expense':'fare_adjustment','amount'=>$amount],['account'=>$kind==='refund'?'manual_cash_paid':'customer_credit','user'=>(int)$trip['customer_id'],'amount'=>-$amount]],$evidence);if($kind==='refund')sql('UPDATE rs_trips SET payment_status=?,version=version+1 WHERE id=?',[$refunded+$amount===$collected?'refunded':'partially_refunded',$trip['id']]);return;
 }
 if($kind==='payout'){
  settlement_guard((int)$r['user_id']);$readiness=driver_readiness((int)$r['user_id']);if(($readiness['profile']['identity_status']??'pending')!=='approved')fail(409,'Driver identity must be reviewed before settlement execution.');
  $amount=(int)($p['amount_minor']??0);$earned=-(int)sql('SELECT COALESCE(SUM(amount_minor),0) FROM rs_entries WHERE user_id=? AND account_key="driver_payable"',[$r['user_id']])->fetchColumn();$held=(int)sql('SELECT COALESCE(SUM(amount_minor),0) FROM rs_entries WHERE user_id=? AND account_key="driver_cash_held"',[$r['user_id']])->fetchColumn();if($amount<=0||$amount>max(0,$earned-max(0,$held)))fail(422,'Payout exceeds driver payable after retained cash and pending collections.');
  $destination=row('SELECT id,payload FROM rs_requests WHERE id=? AND user_id=? AND kind="payout_destination" AND status="executed"',[$p['destination_request']??'', $r['user_id']]);if(!$destination)fail(409,'A reviewed settlement destination is required.');
  journal($u,'manual_payout','payout:'.$r['id'],null,[['account'=>'driver_payable','user'=>(int)$r['user_id'],'amount'=>$amount],['account'=>'manual_cash_paid','amount'=>-$amount]],j(['execution'=>$evidence,'destination_snapshot'=>$p['destination_snapshot'],'destination_request'=>$destination['id']]));return;
 }
