 if($kind==='terms'){sql('INSERT INTO rs_terms(kind,version,title,body) VALUES("service",?,?,?)',[required($p,'version',32),required($p,'title',160),required($p,'body',20000)]);return;}
 if($kind==='promotion'){$discount=(int)($p['discount_minor']??0);$uses=(int)($p['maximum_uses']??0);if($discount<1||$uses<1)fail(422,'Choose a positive discount and usage limit.');sql('INSERT INTO rs_promos(code,description,discount_minor,maximum_uses,expires_at) VALUES(?,?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 DAY))',[strtoupper(required($p,'code',32)),required($p,'description',240),$discount,$uses]);return;}
 if($kind==='role_grant'||$kind==='role_revoke'){
  sql('SELECT id FROM rs_users WHERE id=? FOR UPDATE',[$target]);
  $role=required($p,'role',32);if(!isset(PERMISSIONS[$role])||!row('SELECT id FROM rs_users WHERE id=?',[$target]))fail(422,'Choose an existing user and defined role.');if($target===$u['id'])fail(403,'You cannot change your own role grants.');
  if($kind==='role_grant'){if(!in_array($role,['customer','driver','driver_applicant'])&&!row('SELECT id FROM rs_users WHERE id=? AND totp_secret IS NOT NULL',[$target]))fail(422,'Privileged MFA must be provisioned before a staff grant.');sql('INSERT INTO rs_roles(user_id,role_key,expires_at) VALUES(?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 90 DAY)) ON DUPLICATE KEY UPDATE expires_at=VALUES(expires_at)',[$target,$role]);}else sql('DELETE FROM rs_roles WHERE user_id=? AND role_key=?',[$target,$role]);sql('UPDATE rs_sessions SET revoked_at=UTC_TIMESTAMP() WHERE user_id=?',[$target]);return;
 }
 if(in_array($kind,['restriction','reinstatement','appeal'])){restriction_execute($u,$r,$p,$evidence);return;}
